  "claims": [
    {
      "claim": "The query contains a 4-phenylpiperidine-4-carboxylic acid core, the same scaffold as pethidine; pethidine showed systemic availability of 0.80 ± 0.15 after oral dosing, well above the 20% threshold.",
      "card_ids": ["C05", "C19"]
    },
    {
      "claim": "Setipiprant, which also contains a carboxylic acid, showed human oral bioavailability of at least 50%, indicating that the query's carboxylic acid group is not incompatible with F >= 20%.",
      "card_ids": ["C11"]
    },
    {
      "claim": "Ampicillin, a zwitterionic drug, had oral bioavailability of 29% in fasted female subjects, showing that the query's zwitterionic character is not affirmative evidence for F < 20%.",
      "card_ids": ["C07"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C05", "C19", "C11", "C07"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule; prediction relies on transfer from structurally related contexts.",
    "The query is a zwitterion with logD -0.74 and neutral fraction 0 at pH 7.4, so passive permeability may be low, but no experimental permeability or transporter data are available.",
    "The most similar context (pethidine) was measured in cirrhosis patients, while the query condition is unspecified; dose and formulation also differ.",
    "No visible context exactly matches the query's 4-cyanophenyl-cyclohexyl N-substituent."
  ],
  "decision_summary": "All visible L1 gold records report absolute oral bioavailability above the 20% threshold (roughly 24-80%). The query shares a 4-phenylpiperidine core with pethidine (F=0.80) and a carboxylic acid with setipiprant (F>=50%); ampicillin demonstrates that zwitterionic character can still yield F=29%. The unfavorable permeability prior is not affirmative low evidence, so F >= 20% is better supported."
}

